#include "mgt_cuda/bf16_residual_stack.cuh"
#include <cstdint>
namespace { template<class T>T* Fake(std::uintptr_t p){return reinterpret_cast<T*>(p);} }
int main(){mgt_cuda::Bf16ResidualStackBindings b{};if(mgt_cuda::ValidateBf16ResidualStackBindings(b,false)!=mgt::Status::kInvalidConfig)return 1;b.input_activation=Fake<__nv_bfloat16>(0x1000);for(unsigned layer=0;layer<32;++layer){unsigned site=layer+2;b.weights[layer]=Fake<__nv_bfloat16>(0x2000+layer*0x100);b.weight_grads[layer]=Fake<float>(0x8000+layer*0x100);b.gamma[site]=Fake<float>(0x10000+site*0x100);b.beta[site]=Fake<float>(0x20000+site*0x100);b.running_mean[site]=Fake<float>(0x30000+site*0x100);b.running_variance[site]=Fake<float>(0x40000+site*0x100);b.saved_mean[site]=Fake<float>(0x50000+site*0x100);b.saved_inv_std[site]=Fake<float>(0x60000+site*0x100);b.dgamma[site]=Fake<float>(0x70000+site*0x100);b.dbeta[site]=Fake<float>(0x80000+site*0x100);}if(mgt_cuda::ValidateBf16ResidualStackBindings(b,false)!=mgt::Status::kOk||mgt_cuda::ValidateBf16ResidualStackBindings(b,true)!=mgt::Status::kOk)return 2;b.weights[17]=nullptr;if(mgt_cuda::ValidateBf16ResidualStackBindings(b,false)!=mgt::Status::kInvalidConfig)return 3;b.weights[17]=Fake<__nv_bfloat16>(0x9990);b.dgamma[9]=nullptr;if(mgt_cuda::ValidateBf16ResidualStackBindings(b,true)!=mgt::Status::kInvalidConfig)return 4;b.batch_norm_epsilon=0;if(mgt_cuda::ValidateBf16ResidualStackBindings(b,false)!=mgt::Status::kInvalidConfig)return 5;return 0;}
